input.content:
// Shared plumbing for this pack's checks.
//
// Deliberately dependency-free, and deliberately NOT importing the sibling
// browser-speech pack's copy of the same helpers: a pack composes by declaration,
// never by importing another pack's code (pack independence), and a local pack's
// check modules must load even when the gitignored canon mount is absent — the
// project's own vitest run is exactly that situation.

/** The plain finding object the checks runner consumes (engine/checks/README.md). */
export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
  return {
    rule: rule.id,
    severity: severity || rule.severity,
    file,
    line,
    what,
    why: why || rule.why,
    fix,
    doc: rule.doc,
  };
}

// String-aware comment stripper. Every rule here matches against source *code*: a
// comment that merely names `dispatchEvent` or `MutationObserver` describes the
// trap, it doesn't spring it — and this pack's own prose would otherwise fire its
// own checks. Newlines are preserved so line numbers survive the strip.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// What counts as shipped browser source. Deliberately NOT a hard-coded project
// root: every rule in this pack is gated on the DOM API it judges actually
// appearing in the file, so the trigger is the API usage itself and the scan can
// safely be repo-shaped. A path scope hard-wired to one project's layout would
// make every rule match zero files — and pass VACUOUSLY GREEN — in any repo laid
// out differently, which is the worst failure mode a check has.
//
// The one thing the scan must still exclude is test scaffolding: a test that
// dispatches a bare event at its own jsdom node, or spins an observer it lets the
// test runner collect, is doing something purpose-built and is not adapting to a
// host page. That exclusion is expressed directly — by test/vendor path and test
// filename — instead of being a side effect of the source root.
const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
const NOT_SOURCE = [
  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
];
export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));

/** 1-based line number of `index` in `text`. */
export const lineOf = (text, index) => text.slice(0, index).split('\n').length;

/**
 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
 * brackets), or null when the source is unbalanced — a half-written file should
 * make a check say nothing, never guess. String and template literals are skipped
 * so a bracket inside "a(b)" can't be read as syntax.
 */
export function balanced(src, open) {
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      const quote = c;
      for (i += 1; i < src.length; i++) {
        if (src[i] === '\\') { i += 1; continue; }
        if (src[i] === quote) break;
      }
      continue;
    }
    if (c === '{' || c === '[' || c === '(') depth += 1;
    else if (c === '}' || c === ']' || c === ')') {
      depth -= 1;
      if (depth === 0) return src.slice(open, i + 1);
    }
  }
  return null;
}

/**
 * The UI event interfaces that model **real user input**. These are the ones a
 * host page's own handlers are written against, so a synthetic one is only a
 * faithful stand-in for a user if it looks like what the browser would have
 * produced. `CustomEvent` is deliberately absent: it is your own signal to your
 * own listener and has no fidelity contract to hold it to.
 */
export const INPUT_EVENT_CLASSES = [
  'KeyboardEvent',
  'MouseEvent',
  'PointerEvent',
  'TouchEvent',
  'WheelEvent',
  'InputEvent',
  'DragEvent',
  'CompositionEvent',
];

const INPUT_EVENT_RE = new RegExp(`\\b(?:${INPUT_EVENT_CLASSES.join('|')})\\b`);

/**
 * The constructor names in `src` that stand for a real-input event — the classes
 * themselves, plus the ONE hop real code actually takes: a local alias assigned
 * from them. Picking the constructor by feature (`const Ctor = key ? view.KeyboardEvent
 * : view.MouseEvent`) is how a generic `fire()` helper is written, and a matcher
 * that only knew the literal class names would look straight past the single
 * dispatch site a whole adapter funnels its input through.
 */
export function inputEventCtors(src) {
  const names = new Set(INPUT_EVENT_CLASSES);
  const ALIAS = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\n]*)/g;
  let m;
  while ((m = ALIAS.exec(src))) {
    if (INPUT_EVENT_RE.test(m[2])) names.add(m[1]);
  }
  return names;
}

/**
 * Every `new <ctor>(…)` construction in `src` whose constructor is one of `names`
 * (an optional `view.` / `window.` / `globalThis.` receiver is allowed — a content
 * script constructing an event for another frame's document must use THAT window's
 * constructor). Returns `{ name, index, args, init }`, where `init` is the second
 * argument's object literal, or null when the call passes no init literal at all.
 */
export function eventConstructions(src, names) {
  const NEW = /\bnew\s+(?:(?:window|globalThis|self|view|win)\s*\.\s*)?([A-Za-z_$][\w$]*)\s*\(/g;
  const out = [];
  let m;
  while ((m = NEW.exec(src))) {
    if (!names.has(m[1])) continue;
    const args = balanced(src, NEW.lastIndex - 1);
    if (args === null) continue; // unbalanced source: say nothing
    const brace = args.indexOf('{');
    const init = brace === -1 ? null : balanced(args, brace);
    out.push({ name: m[1], index: m.index, args, init });
  }
  return out;
}

/** Does an init object literal spread something this check cannot see into? */
export const hasSpread = (init) => init !== null && init.includes('...');

import { finding, stripComments, isSource, lineOf } from './lib.mjs';

// A DOM observer you start on a page you do not own runs until you disconnect it
// or the document dies — and the document of a single-page app you are a guest in
// does not die. Everything else that ends your feature (the session stopped, the
// element you were waiting for arrived, your UI unmounted) ends nothing for the
// observer: it keeps waking on every mutation the host makes, forever, holding
// its callback's whole closure alive with it.
//
// On a host page that is not merely a leak. It is the difference between "off"
// and "off but still watching": a MutationObserver left on a busy app fires
// thousands of times a minute, and any work its callback does — a snapshot, a
// diff, a re-render of your own injected UI — is work the user did not ask for
// on a page that is not yours. An extension that promises to be inert when idle
// cannot keep that promise with a live observer in the page.
//
// Deliberately file-scoped rather than flow-scoped: proving that a PARTICULAR
// observer is disconnected on every path needs real data-flow analysis, and a
// check that guesses is worse than one that asks a simple, honest question —
// "this file starts an observer on the page; does it anywhere disconnect one?".
// A file that constructs an observer but never calls `.observe(` has started
// nothing and is not asked. Comments are stripped first.

const OBSERVER = /\b(?:Mutation|Intersection|Resize)Observer\b/;
const CONSTRUCT = /\bnew\s+(?:[A-Za-z_$][\w$]*\s*\.\s*)?(?:Mutation|Intersection|Resize)Observer\s*\(/g;
const STARTED = /\.\s*observe\s*\(/;
const STOPPED = /\.\s*disconnect\s*\(/;

const rule = {
  id: 'page-observers-disconnected',
  severity: 'blocking',
  description: 'A file that starts a DOM observer also disconnects one',
  doc: '.claudinite/local/packs/host-page-adaptation/RULES.md',
  why: 'an observer on a host page outlives whatever started it — the single-page app never unloads, so "stopped" work keeps waking on every host mutation and the guest is never really inert',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !OBSERVER.test(raw)) continue;
      const src = stripComments(raw);
      CONSTRUCT.lastIndex = 0;
      const first = CONSTRUCT.exec(src);
      if (!first) continue;
      if (!STARTED.test(src)) continue; // constructed but never started: watches nothing
      if (STOPPED.test(src)) continue;
      out.push(finding(rule, {
        file,
        line: lineOf(src, first.index),
        what: 'starts a DOM observer on the page but never disconnects one',
        fix: 'call observer.disconnect() on every path that ends the work it was watching for — the moment a one-shot observer sees what it was waiting for, and in the teardown of anything session-scoped',
      }));
    }
    return out;
  },
};

export default rule;

import {
  finding, stripComments, isSource, lineOf, balanced,
  inputEventCtors, eventConstructions, hasSpread,
} from './lib.mjs';

// A real click or keystroke bubbles. A synthetic one only bubbles if you say so:
// `bubbles` defaults to FALSE on every DOM event constructor, so
// `el.dispatchEvent(new MouseEvent('click'))` fires an event that reaches
// listeners on `el` and stops dead there.
//
// On your own markup you rarely notice, because you attached the listener to the
// node you dispatched at. On a host page you always notice, because you never
// attached anything: the app you are driving handles input by DELEGATION, one
// listener near its own root, and an event that does not bubble never arrives.
// The failure is silent in the worst way — dispatchEvent returns true, no
// exception, no console message, and the page simply does not respond. It is
// indistinguishable from "the app ignores untrusted events", which is the wrong
// conclusion to reach and an expensive one to back out of.
//
// Scoped to the event interfaces that model REAL USER INPUT (lib.mjs
// INPUT_EVENT_CLASSES) at a `dispatchEvent` site. A CustomEvent is your own signal
// to your own listener and is legitimately non-bubbling, so it is never judged.
// The constructor is resolved through one alias hop, because a generic `fire()`
// helper — the shape an adapter that funnels ALL its synthetic input through one
// place actually has — picks its constructor by feature rather than naming a class
// at the dispatch site.
//
// An init literal that spreads something (`{ ...init }`) is beyond what this check
// can see, so it says nothing: the fields may well be set by the caller. That is
// the deliberate quiet direction — a check on a fidelity contract earns its keep
// by never crying wolf on code it cannot read.

const DISPATCH = /\.\s*dispatchEvent\s*\(/g;
const BUBBLES_TRUE = /\bbubbles\s*:\s*(?:true|!0)\b/;
const BUBBLES_ANY = /\bbubbles\s*:/;

const rule = {
  id: 'synthetic-input-events-bubble',
  severity: 'blocking',
  description: 'A dispatched user-input event sets bubbles: true',
  doc: '.claudinite/local/packs/host-page-adaptation/RULES.md',
  why: 'bubbles defaults to false on every event constructor, and a host page handles input by delegation near its own root — a non-bubbling synthetic event never reaches the handler, silently, and reads as "the app ignores untrusted events"',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !raw.includes('dispatchEvent')) continue;
      const src = stripComments(raw);
      const ctors = inputEventCtors(src);

      DISPATCH.lastIndex = 0;
      let call;
      while ((call = DISPATCH.exec(src))) {
        const args = balanced(src, DISPATCH.lastIndex - 1);
        if (args === null) continue;
        for (const { name, init } of eventConstructions(args, ctors)) {
          if (init === null) {
            out.push(finding(rule, {
              file,
              line: lineOf(src, call.index),
              what: `dispatches a ${name} constructed with no init, so it does not bubble`,
              fix: `pass { bubbles: true, cancelable: true, composed: true } to the ${name} constructor — a real user event carries all three, and a page that handles input by delegation only ever sees the ones that bubble`,
            }));
            continue;
          }
          if (BUBBLES_TRUE.test(init)) continue;
          if (hasSpread(init) && !BUBBLES_ANY.test(init)) continue; // spread may set it: unreadable, so silent
          out.push(finding(rule, {
            file,
            line: lineOf(src, call.index),
            what: `dispatches a ${name} that does not set bubbles: true`,
            fix: `set bubbles: true in the ${name} init — without it the event stops at the node you dispatched it on and never reaches the delegated handler the host page listens with`,
          }));
        }
      }
    }
    return out;
  },
};

export default rule;

import {
  finding, stripComments, isSource, lineOf,
  inputEventCtors, eventConstructions, hasSpread,
} from './lib.mjs';

// `keyCode`, `which` and `charCode` are deprecated, and the browser fills them in
// on every real keystroke anyway. On a synthetic one it does not: they are plain
// init fields that default to 0, so `new KeyboardEvent('keydown', { key: 'A' })`
// arrives at the page as a keystroke whose keyCode is 0.
//
// Deprecated is not the same as unread. Host apps — especially anything with a
// long-lived key-handling layer, or a framework version predating `key` support —
// still branch on the legacy fields, and a 0 matches nothing: the event is
// received, the handler runs, and nothing happens. You cannot fix that by asking
// the host to modernise, and you cannot see it from your side except as "the page
// ignored my keystroke". The only cost of setting all three is three properties;
// the cost of omitting them is a fidelity bug that looks like a permissions one.
//
// Judged only where the init is READABLE: an init that spreads (`{ ...init }`)
// may well carry the fields from its caller, and a check that guessed there would
// false-alarm on exactly the well-factored helper that centralises this. Named
// classes and one alias hop both count as the constructor (lib.mjs
// inputEventCtors), so a `fire()` helper picking KeyboardEvent by feature is in
// scope for the day someone hand-writes its init.

const KEY_FIELD = /\bkey\s*:/;
const LEGACY = /\b(?:keyCode|which|charCode)\s*:/;

const rule = {
  id: 'synthetic-key-events-legacy-fields',
  severity: 'blocking',
  description: 'A synthetic KeyboardEvent init carries keyCode/which',
  doc: '.claudinite/local/packs/host-page-adaptation/RULES.md',
  why: 'the legacy key fields are filled in by the browser on a real keystroke and default to 0 on a synthetic one, so a host handler that still branches on keyCode matches nothing and silently does nothing',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !raw.includes('KeyboardEvent')) continue;
      const src = stripComments(raw);
      // Only constructors that can be a KeyboardEvent — a MouseEvent has no key
      // fields to be missing, so the alias set is narrowed to this one class.
      const ctors = inputEventCtors(src);
      for (const name of [...ctors]) {
        if (name !== 'KeyboardEvent' && !aliasOfKeyboardEvent(src, name)) ctors.delete(name);
      }

      for (const { init, index } of eventConstructions(src, ctors)) {
        if (init === null) continue; // no init at all is the bubbles rule's finding, not this one
        if (!KEY_FIELD.test(init)) continue; // not describing a keystroke by name
        if (LEGACY.test(init)) continue;
        if (hasSpread(init)) continue; // unreadable: the caller may carry them
        out.push(finding(rule, {
          file,
          line: lineOf(src, index),
          what: 'builds a synthetic key event with `key` but no keyCode/which, so both arrive as 0',
          fix: "set keyCode and which alongside key (and charCode on keypress) — e.g. { key: 'A', code: 'KeyA', keyCode: 65, which: 65 } — so the event matches what the browser produces for a real keystroke",
        }));
      }
    }
    return out;
  },
};

// An alias counts for THIS rule only when its right-hand side can yield a
// KeyboardEvent: `const Ctor = isKey ? view.KeyboardEvent : view.MouseEvent` can,
// `const Ctor = view.MouseEvent` cannot.
function aliasOfKeyboardEvent(src, name) {
  const re = new RegExp(`\\b(?:const|let|var)\\s+${name}\\s*=\\s*([^;\\n]*)`);
  const m = re.exec(src);
  return Boolean(m && /\bKeyboardEvent\b/.test(m[1]));
}

export default rule;

import pageObserversDisconnected from './page-observers-disconnected.mjs';
import syntheticInputEventsBubble from './synthetic-input-events-bubble.mjs';
import syntheticKeyEventsLegacyFields from './synthetic-key-events-legacy-fields.mjs';

// host-page-adaptation — being a guest in a web app you do not own: reading its
// DOM, driving it with synthetic input, watching it change, and injecting your
// own UI into it, all against markup that can be redesigned without notice.
//
// Every rule here judges a DOM/API contract that holds for any code driving a
// third-party page — a userscript, a browser automation layer, an extension's
// content script — and its scan is repo-shape agnostic (see lib.mjs `isSource`)
// so it cannot pass vacuously green somewhere laid out differently. It lives
// locally only because the mounted canon has no home for this facet: the
// chrome-extension pack covers MV3 manifest/permission/content-script MECHANICS
// (how to get your code onto the page) and says nothing about what to do once it
// is there, and node / github-actions / chrome-extension-release /
// spec-driven-product / executable-requirements are orthogonal. Declared by hand
// as `local/host-page-adaptation` in .claudinite-checks.json.
export default {
  id: 'host-page-adaptation',
  ruleRoutingGuidance: {
    belongs: 'driving a web app you do not own from inside its page — host DOM reads, synthetic input, change watching, injected UI, and surviving the host\'s redesigns',
    excludes: 'how extension code gets onto the page at all (manifest, permissions, content-script registration) — that is chrome-extension; speech APIs are local/browser-speech',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [
    pageObserversDisconnected,
    syntheticInputEventsBubble,
    syntheticKeyEventsLegacyFields,
  ],
};

// Red-first fixtures for the host-page-adaptation pack's checks.
//
// Every rule is exercised three ways: it must FIRE on a violating source, stay
// QUIET on a clean one, and stay quiet on the repo's real extension/src/ tree.
// The third case is what makes the pack shippable — a check that only ever saw
// its own fixtures is a check nobody has confronted with real code.
//
// Runs in the project's own vitest (see the .claudinite/local/packs include in
// vitest.config.js) and imports nothing from the gitignored canon mount, so it
// works in CI exactly as it does locally.

import { describe, test, expect } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

import pack from './pack.mjs';
import { isSource } from './lib.mjs';
import pageObserversDisconnected from './page-observers-disconnected.mjs';
import syntheticInputEventsBubble from './synthetic-input-events-bubble.mjs';
import syntheticKeyEventsLegacyFields from './synthetic-key-events-legacy-fields.mjs';

// A check context over a literal file map — the same {files, read} surface the
// engine's runner passes, with nothing else the rules are allowed to touch.
const ctxOf = (files) => ({
  files: Object.keys(files),
  read: (f) => (f in files ? files[f] : null),
});

const run = (rule, files) => rule.run(ctxOf(files));

describe('host-page-adaptation pack manifest', () => {
  test('is a hand-declared local pack whose rules are all wired', () => {
    expect(pack.id).toBe('host-page-adaptation'); // must equal the directory name
    expect(pack.detect).toBeNull();
    expect(pack.marker).toBeNull();
    expect(pack.prose).toBe('RULES.md');
    expect(pack.worldRules.map((r) => r.id).sort()).toEqual([
      'page-observers-disconnected',
      'synthetic-input-events-bubble',
      'synthetic-key-events-legacy-fields',
    ]);
  });
});

// The scan must be repo-shape agnostic: a rule that only ever looks under one
// project's source root matches nothing — and passes vacuously green — in a repo
// laid out differently, which is exactly the bug these cases exist to prevent.
describe('source scope', () => {
  test('accepts browser source under any layout, in JS and TS alike', () => {
    for (const file of [
      'extension/src/page-adapter/writer.js',
      'src/adapter.ts',
      'app/lib/host.tsx',
      'packages/web/inject.mjs',
      'userscript.cjs',
    ]) expect(isSource(file), file).toBe(true);
  });

  test('rejects test scaffolding, fixtures and vendored code wherever they sit', () => {
    for (const file of [
      'extension-test/integration/page-adapter.test.js',
      'extension-test/fixtures/fake-nyt/fake-app.js',
      'src/adapter.spec.ts',
      'test/host.js',
      'node_modules/x/index.js',
      'dist/content.js',
      'README.md',
    ]) expect(isSource(file), file).toBe(false);
  });
});

describe('page-observers-disconnected', () => {
  test('fires on an observer started and never disconnected', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        export function watch(document, onChange) {
          const observer = new MutationObserver(onChange);
          observer.observe(document.body, { childList: true, subtree: true });
        }
      `,
    });
    expect(found.map((f) => f.rule)).toEqual(['page-observers-disconnected']);
    expect(found[0].file).toBe('src/mount.js');
    expect(found[0].severity).toBe('blocking');
  });

  test('fires on an IntersectionObserver and a ResizeObserver too', () => {
    for (const cls of ['IntersectionObserver', 'ResizeObserver']) {
      const found = run(pageObserversDisconnected, {
        'app/host.ts': `const o = new ${cls}(cb); o.observe(el);`,
      });
      expect(found.length, cls).toBe(1);
    }
  });

  test('fires when the observer is constructed off a window reference', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        const view = document.defaultView;
        const observer = new view.MutationObserver(schedule);
        observer.observe(document.documentElement, { subtree: true, childList: true });
      `,
    });
    expect(found.length).toBe(1);
  });

  test('quiet when the observer disconnects (one-shot mount)', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        export function mountWhenReady(document, place) {
          const observer = new MutationObserver(() => {
            const host = document.querySelector('[class*="toolbar"]');
            if (!host) return;
            observer.disconnect();
            place(host);
          });
          observer.observe(document.documentElement, { childList: true, subtree: true });
        }
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet when an observer is constructed but never started', () => {
    const found = run(pageObserversDisconnected, {
      'src/factory.js': 'export const makeObserver = (cb) => new MutationObserver(cb);',
    });
    expect(found).toEqual([]);
  });

  test('quiet on a comment that merely names the trap', () => {
    const found = run(pageObserversDisconnected, {
      'src/notes.js': `
        // A MutationObserver started here would need observer.observe(...) and
        // an observer.disconnect() in teardown.
        export const nothing = 1;
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet in test scaffolding that leaves its observer to the runner', () => {
    const found = run(pageObserversDisconnected, {
      'test/watch.test.js': 'const o = new MutationObserver(cb); o.observe(document.body, {});',
    });
    expect(found).toEqual([]);
  });
});

describe('synthetic-input-events-bubble', () => {
  test('fires on an input event dispatched with no init at all', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new MouseEvent('click'));",
    });
    expect(found.map((f) => f.rule)).toEqual(['synthetic-input-events-bubble']);
    expect(found[0].what).toContain('MouseEvent');
  });

  test('fires on an init that omits bubbles', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "target.dispatchEvent(new KeyboardEvent('keydown', { key: 'A', keyCode: 65, which: 65 }));",
    });
    expect(found.length).toBe(1);
  });

  test('fires on an explicit bubbles: false', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: false, cancelable: true }));",
    });
    expect(found.length).toBe(1);
  });

  test('fires through a one-hop constructor alias — the generic fire() helper', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': `
        function fire(el, type, init) {
          const Ctor = type.startsWith('key') ? window.KeyboardEvent : window.MouseEvent;
          el.dispatchEvent(new Ctor(type, { cancelable: true, composed: true }));
        }
      `,
    });
    expect(found.length).toBe(1);
  });

  test('quiet when bubbles: true is set', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, composed: true }));",
    });
    expect(found).toEqual([]);
  });

  test('quiet on an aliased constructor whose init spreads the caller\'s fields', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': `
        function fire(el, type, init) {
          const Ctor = type.startsWith('key') ? view.KeyboardEvent : view.MouseEvent;
          el.dispatchEvent(new Ctor(type, { ...init }));
        }
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet on a CustomEvent — your own signal has no fidelity contract', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new CustomEvent('cc:ready', { detail: { ok: true } }));",
    });
    expect(found).toEqual([]);
  });

  test('quiet on an event that is constructed but never dispatched', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "const probe = new MouseEvent('click'); export const supported = Boolean(probe); el.dispatchEvent(new CustomEvent('x'));",
    });
    expect(found).toEqual([]);
  });

  test('quiet on a comment describing the trap', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/notes.js': `
        // Do not write el.dispatchEvent(new MouseEvent('click')) — bubbles defaults to false.
        export const nothing = 1;
      `,
    });
    expect(found).toEqual([]);
  });
});

describe('synthetic-key-events-legacy-fields', () => {
  test('fires on a bare { key } init', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': "el.dispatchEvent(new KeyboardEvent('keydown', { key: 'A', bubbles: true }));",
    });
    expect(found.map((f) => f.rule)).toEqual(['synthetic-key-events-legacy-fields']);
  });

  test('fires through an alias that can be a KeyboardEvent', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': `
        const Ctor = isKey ? view.KeyboardEvent : view.MouseEvent;
        el.dispatchEvent(new Ctor(type, { key: 'Backspace', bubbles: true, composed: true }));
      `,
    });
    expect(found.length).toBe(1);
  });

  test('quiet when keyCode and which are set', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': "el.dispatchEvent(new KeyboardEvent('keydown', { key: 'A', code: 'KeyA', keyCode: 65, which: 65, bubbles: true }));",
    });
    expect(found).toEqual([]);
  });

  test('quiet when the init spreads a caller-built descriptor', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': `
        const init = keyEventInit(key);
        el.dispatchEvent(new KeyboardEvent(type, { bubbles: true, ...init }));
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet on a MouseEvent-only alias — a mouse event has no key fields to miss', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': `
        const Ctor = view.MouseEvent;
        el.dispatchEvent(new Ctor('click', { key: 'A', bubbles: true }));
        const unrelated = new KeyboardEvent('keyup', { key: 'A', keyCode: 65, which: 65 });
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet on an init that names no key at all', () => {
    const found = run(syntheticKeyEventsLegacyFields, {
      'src/type.js': "el.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, cancelable: true }));",
    });
    expect(found).toEqual([]);
  });
});

// The parsing each rule does has to be shown NECESSARY, not just correct: run the
// quiet fixtures against the naive alternative the parsing exists to avoid and
// confirm they would wrongly fire. That is what earns the complexity.
describe('the parsing earns its keep', () => {
  const NAIVE_BUBBLES = /new\s+\w*Event\s*\(/;
  const NAIVE_KEYS = /\bkey\s*:/;

  test('a whole-file grep for an event construction would false-alarm on the quiet cases', () => {
    for (const src of [
      "el.dispatchEvent(new CustomEvent('cc:ready', { detail: { ok: true } }));",
      "const probe = new MouseEvent('click'); el.dispatchEvent(new CustomEvent('x'));",
      "el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));",
    ]) {
      expect(NAIVE_BUBBLES.test(src), src).toBe(true); // the naive rule fires...
    }
    // ...and the real rule stays quiet on all three.
    expect(run(syntheticInputEventsBubble, {
      'src/a.js': "el.dispatchEvent(new CustomEvent('cc:ready', { detail: { ok: true } }));",
      'src/b.js': "const probe = new MouseEvent('click'); el.dispatchEvent(new CustomEvent('x'));",
      'src/c.js': "el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));",
    })).toEqual([]);
  });

  test('a whole-file grep for `key:` without keyCode would false-alarm on the spread and mouse cases', () => {
    const spread = "const init = keyEventInit(key);\nel.dispatchEvent(new KeyboardEvent(type, { bubbles: true, ...init }));";
    const mouse = "const Ctor = view.MouseEvent;\nel.dispatchEvent(new Ctor('click', { key: 'A', bubbles: true }));";
    for (const src of [spread, mouse]) {
      expect(NAIVE_KEYS.test(src) && !/keyCode/.test(src), src).toBe(true);
    }
    expect(run(syntheticKeyEventsLegacyFields, { 'src/a.js': spread, 'src/b.js': mouse })).toEqual([]);
  });
});

// The corpus case: every rule must be silent on the shipped extension source. A
// pack that goes red on the code it was distilled from is not shippable, and this
// is the only fixture nobody wrote to make a check pass.
describe('the repo\'s real extension source', () => {
  const ROOT = process.cwd();
  const SRC = join(ROOT, 'extension/src');

  const walk = (dir, out = []) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) walk(p, out);
      else out.push(p);
    }
    return out;
  };

  const files = Object.fromEntries(
    walk(SRC).map((p) => [relative(ROOT, p).split(sep).join('/'), readFileSync(p, 'utf8')]),
  );

  test('the corpus is real (the adapter and its dispatch site are in it)', () => {
    expect(files['extension/src/page-adapter/writer.js']).toContain('dispatchEvent');
    expect(files['extension/src/page-adapter/watcher.js']).toContain('MutationObserver');
  });

  for (const rule of pack.worldRules) {
    test(`${rule.id} is quiet on extension/src`, () => {
      expect(run(rule, files)).toEqual([]);
    });
  }
});

